        // 3. Use JAXP's SAXParserFactory to parse the XML content
        SAXParserFactory spf = SAXParserFactory.newInstance();

        // Security: Prevent XXE (XML External Entity) and SSRF vulnerabilities
        spf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        spf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        spf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        spf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        spf.setXIncludeAware(false);
        spf.setNamespaceAware(true);

        SAXParser saxParser = spf.newSAXParser();
        XMLReader xmlReader = saxParser.getXMLReader();

        try (InputStream is = new FileInputStream(configFile)) {
            InputSource inputSource = new InputSource(is);
            SAXSource saxSource = new SAXSource(xmlReader, inputSource);

            // 4. Convert the parsed result into an org.w3c.dom.Document object
            // We use JAXP Transformer to bridge the SAX parsing stream into a DOM tree securely
            TransformerFactory tf = TransformerFactory.newInstance();
            tf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            tf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            tf.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");

            Transformer transformer = tf.newTransformer();
            DOMResult domResult = new DOMResult();

            // This step triggers the SAX parser and builds the DOM Document simultaneously
            transformer.transform(saxSource, domResult);

            return (Document) domResult.getNode();

        } catch (TransformerException e) {
            // Throw an exception when the XML format is invalid or parsing fails
            throw new Exception("Invalid XML format or parsing error: " + e.getMessage(), e);
        } catch (IOException e) {
            throw new Exception("I/O error while reading the configuration file: " + e.getMessage(), e);
        }
    }
}
